"""Generate readable tables directly from the convergence-gated summary."""
import json
from pathlib import Path
import numpy as np
HERE=Path(__file__).resolve().parent
d=json.loads((HERE/'summary.json').read_text())
lines=['# Numerical tables','',
       'Generated by `make_tables.py` from `summary.json`. Coefficients below are finite-scale estimators, not assigned CFT data.','',
       '## Infinite chain, real frame, two-site optimization','',
       '| χ | Energy per site | Mean S₁ | ξ (sites) | Transverse one-point RMS |',
       '|---:|---:|---:|---:|---:|']
primary=next(r for r in d['infinite'] if r['model']=='candidate' and r['cell']==2 and r['gauge'] and not r['one_site'])
for p in primary['points']:
    order=np.sqrt(np.mean(np.array(p['X'])**2+np.array(p['Y'])**2))
    lines.append(f"| {p['chi']} | {p['E_physical']:.12f} | {p['S']:.9f} | {p['xi']:.6f} | {order:.6g} |")
lines+=['','Only accepted states appear. χ32 two-site states fail the sweep-norm gate and are excluded. Low-χ points cross a substantial finite-χ order change.','',
        '## Successive bulk slopes on the nearly symmetric branch','',
        'The estimator is `c_alpha=12 alpha/(alpha+1) Delta S_alpha/Delta log(xi)`.','',
        '| Optimization | χ pair | Order 1 | Order 2 | Order 3 | ξ-versus-χ power |',
        '|---|---|---:|---:|---:|---:|']
for r in d['infinite']:
    if r['model']!='candidate' or r['cell']!=2 or not r['gauge']:continue
    for p in r['pairs']:
        if min(p['chis'])<48:continue
        cs=p['c_renyi'];label='One-site' if r['one_site'] else 'Two-site'
        lines.append(f"| {label} | {p['chis'][0]} → {p['chis'][1]} | {cs['1']:.6f} | {cs['2']:.6f} | {cs['3']:.6f} | {p['xi_chi_power']:.6f} |")
lines+=['','## Periodic entropy','',
        'The selected accepted entropy state is the lowest-energy accepted parity state; availability of independent parity energy checks is explicit. No entropy from a failed gate enters these estimates.','',
        '| L | Parity | χ | Fractional-window S₁ | Middle-half profile coefficient | Middle-quarter profile coefficient | Both DMRG parity energy gates pass |',
        '|---:|---:|---:|---:|---:|---:|---|']
for p in d['periodic_selected']:
    if p['model']!='candidate':continue
    s=p['entropy_stats']['1'];pr=s['profiles']
    lines.append(f"| {p['L']} | {p['parity']} | {p['chi']} | {s['fractional']:.9f} | {pr['0.25']['c']:.6f} | {pr['0.375']['c']:.6f} | {p['both_parity_energy_gates_pass']} |")
lines+=['','| L pair | Periodic central-three coefficient | Periodic fractional coefficient |','|---|---:|---:|']
for p in d['periodic_pairs']:
    if p['model']=='candidate':lines.append(f"| {p['L'][0]} → {p['L'][1]} | {p['c']['1']['central3']:.6f} | {p['c']['1']['fractional']:.6f} |")
lines+=['','## Odd-even energy differences','',
        'ED covers every momentum. DMRG differences require every energy gate, but do not require a stationary entropy inside a degenerate sector. Finite-χ energy differences are not rigorous bounds on the gap.','',
        '| Method | L | χ even/odd | E_odd − E_even | L times difference |','|---|---:|---|---:|---:|']
for L in [16,20,24]:
    p=json.loads((HERE/f'dispersion_L{L}.json').read_text())
    if p['complete']:lines.append(f"| ED | {L} | exact | {p['parity_gap']:.10f} | {L*p['parity_gap']:.8f} |")
for p in d['periodic_parity_gaps']:
    if p['model']=='candidate':lines.append(f"| DMRG | {p['L']} | {p['chis'][0]}/{p['chis'][1]} | {p['gap']:.10f} | {p['L_gap']:.8f} |")
lines+=['','## Finite-ring bond-dimension changes','',
        'Both endpoint states pass all entropy gates. A two-χ difference is a sensitivity check, not an error bound.','',
        '| L | Parity | χ pair | Energy change | Fractional S₁ change |','|---:|---:|---|---:|---:|']
for p in d['periodic_bond_checks']:
    if p['model']=='candidate':lines.append(f"| {p['L']} | {p['parity']} | {p['chis'][0]} → {p['chis'][1]} | {p['delta_E']:.8g} | {p['delta_S']['1']['fractional']:.8g} |")
lines+=['','| L | Matched χ | Odd-even difference |','|---:|---:|---:|']
for p in d['periodic_matched_chi_gaps']:
    if p['model']=='candidate':lines.append(f"| {p['L']} | {p['chi']} | {p['gap']:.10f} |")
lines+=['','## XX calibration','',
        '| χ fit window | Ordinary-entropy coefficient | Rényi-2 | Rényi-3 |','|---|---:|---:|---:|']
control=next(r for r in d['infinite'] if r['model']=='xx' and r['seed']==23)
for p in control['fits']:
    cs=p['c_renyi'];lines.append(f"| {', '.join(map(str,p['chis']))} | {cs['1']:.6f} | {cs['2']:.6f} | {cs['3']:.6f} |")
lines+=['','## Ising critical and massive controls','',
        'H = −sum XX − h sum Z. The h=1 reference is critical with c=1/2; h=1.01 has exact fermion gap 0.02. `ising_controls.json` compares energies with the independently validated free-fermion integral.','',
        '| Model | Update | χ | S₁ | ξ | Successive ordinary-entropy coefficient |','|---|---|---:|---:|---:|---:|']
for r in d['infinite']:
    if r['model'] not in ['ising_critical','ising_gapped']:continue
    pair_lookup={p['chis'][1]:p['c'] for p in r['pairs']}
    for p in r['points']:
        coefficient=f"{pair_lookup[p['chi']]:.6f}" if p['chi'] in pair_lookup else '—'
        method='one-site' if r['one_site'] else 'two-site'
        lines.append(f"| {r['model']} | {method} | {p['chi']} | {p['S']:.9f} | {p['xi']:.6f} | {coefficient} |")
lines+=['','## Excluded or unfinished records','',
        '| Record | Status | Failed gates |','|---|---|---|']
for p in d['inventory']:
    if not p['converged']:
        failed=', '.join(k for k,v in (p.get('convergence_checks') or {}).items() if not v)
        lines.append(f"| [{Path(p['source']).stem}]({p['source']}) | {p['status']} | {failed} |")
lines+=['','Setup failures before any optimization are separately retained in `setup_failures.json`.','']
(HERE/'NUMERICS.md').write_text('\n'.join(lines))
